import{_ as e,c as n,o as t,ag as s}from"./chunks/framework.Bzez9NG9.js";const u=JSON.parse('{"title":"Custom packages","description":"Install and manage additional Python packages in the SPACE Python and Jupyter environment.","frontmatter":{"title":"Custom packages","description":"Install and manage additional Python packages in the SPACE Python and Jupyter environment.","keywords":["Python packages","pip","dependencies","requirements-custom.txt","package installation","Python environment"],"outline":"deep"},"headers":[],"relativePath":"doc/python/custom-packages.md","filePath":"doc/python/custom-packages.md"}'),i={name:"doc/python/custom-packages.md"};function o(p,a,r,c,d,l){return t(),n("div",null,a[0]||(a[0]=[s(`<h1 id="custom-packages" tabindex="-1">Custom packages <a class="header-anchor" href="#custom-packages" aria-label="Permalink to &quot;Custom packages&quot;">​</a></h1><p>SPACE includes the Python packages required by the platform and allows additional packages to be installed for client-specific scripts and notebooks.</p><p>Use custom packages when a Python workflow depends on a library that is not included in the standard SPACE Python environment.</p><h2 id="managing-custom-packages" tabindex="-1">Managing custom packages <a class="header-anchor" href="#managing-custom-packages" aria-label="Permalink to &quot;Managing custom packages&quot;">​</a></h2><p>Custom packages are managed for the SPACE Python environment rather than installed separately inside each notebook.</p><p>Administrators can add packages to the custom Python requirements and apply the updated package configuration to the Python service. Packages can also be upgraded or removed when requirements change.</p><p>Once installed, a package is available to Python scripts and Jupyter notebooks running in that SPACE environment.</p><h2 id="package-requirements" tabindex="-1">Package requirements <a class="header-anchor" href="#package-requirements" aria-label="Permalink to &quot;Package requirements&quot;">​</a></h2><p>Custom Python dependencies are maintained in <code>requirements-custom.txt</code>.</p><p>Standard pip requirement syntax can be used, including version constraints when a workflow requires a particular package version.</p><p>For example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>requests</span></span>
<span class="line"><span>pandas&gt;=2.0</span></span>
<span class="line"><span>some-package==1.2.3</span></span></code></pre></div><p>Pin versions when reproducibility is important, particularly for production automation.</p><h2 id="installing-and-updating-packages" tabindex="-1">Installing and updating packages <a class="header-anchor" href="#installing-and-updating-packages" aria-label="Permalink to &quot;Installing and updating packages&quot;">​</a></h2><p>SPACE administrators can manage the custom Python package set as part of the SPACE Python service configuration.</p><p>When adding a library, include it in the custom requirements so the dependency remains part of the environment rather than relying on a temporary installation from an individual notebook.</p><p>This is preferable to running ad hoc <code>pip install</code> commands in notebooks because the required packages remain explicit and can be reproduced when the Python service is updated or redeployed.</p><h2 id="using-packages" tabindex="-1">Using packages <a class="header-anchor" href="#using-packages" aria-label="Permalink to &quot;Using packages&quot;">​</a></h2><p>After a package is available in the environment, import it normally from a script or notebook:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> requests</span></span></code></pre></div><p>See <a href="./scripts.html">Python scripts</a> and <a href="./jupyter.html">Jupyter</a> for the two primary execution workflows.</p><p>For IBM Planning Analytics development, see <a href="./tm1py.html">TM1py</a>.</p>`,22)]))}const g=e(i,[["render",o]]);export{u as __pageData,g as default};
